import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"Organizar automatizaciones","description":"","frontmatter":{"title":"Organizar automatizaciones","docId":"user.automations.index","translationKey":"user.automations.index","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"08bb26a20687b58094e908a4e8395abeae3b9adc3932c86d9c3b08f5ebbf8ce3","translationRevision":"e07b6c18b1612695a62ba9139ffa993b4f6dac943ff75b63e0bda15618f3568a","order":10},"headers":[],"relativePath":"es/user/automations/index.md","filePath":"es/user/automations/index.md","lastUpdated":1795727787000}`),s={name:`es/user/automations/index.md`};function c(a,o,s,c,l,u){let d=e(`DemoFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="organize-automations" tabindex="-1">Organizar automatizaciones <a class="header-anchor" href="#organize-automations" aria-label="Permalink to “Organizar automatizaciones”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objetivo y requisitos”">​</a></h2><p>Construye una biblioteca pequeña y comprensible que responda a eventos LIVE. Necesitas el host de escritorio funcionando. Una <a href="./../live/connections.html">conexión LIVE</a> real permite validar eventos externos; las acciones de plugins también requieren su plugin y servicio preparados.</p><h2 id="understand-the-library" tabindex="-1">Comprender la biblioteca <a class="header-anchor" href="#understand-the-library" aria-label="Permalink to “Comprender la biblioteca”">​</a></h2><p>Una <strong>Action</strong> es una operación reutilizable configurada, como escribir una línea o reproducir sonido. Un <strong>Event</strong> elige disparador, filtros, espera y acciones vinculadas. Un perfil agrupa definiciones para un flujo de trabajo; solo hay un paquete de perfil activo a la vez. Las <a href="./variables.html">Variables</a> proporcionan valores reutilizables por varias acciones.</p><ol><li>Abre <strong>Automations</strong> y confirma el perfil activo antes de editar. Busca Eventos y Acciones por separado para saber qué tipo de registro seleccionas.</li><li>Comienza con la <a href="./first-rule.html">primera regla de registro</a>. Crea la acción y después el evento que la referencia.</li><li>Elige un disparador admitido por el host. Añade filtros mediante el selector de campos correspondiente. Varias condiciones restringen la coincidencia; no modifican el contenido entrante.</li><li>Define el tiempo de espera y su ámbito. Una espera global limita la regla entre todos los espectadores; una espera por usuario los controla por separado.</li><li>Vincula las acciones deseadas en orden. El modo normal ejecuta la lista elegida; el aleatorio selecciona una acción. Una acción de demora pospone las posteriores sin frenar la recepción LIVE.</li><li>Guarda, revisa los cambios de definición que se muestren y activa explícitamente los registros deseados. Consulta el historial para comprobar nombre, resultado y error.</li></ol><p>Toda comparación admite una lista de valores en lugar de un solo valor. La combinación predeterminada es «cualquiera»: la condición se cumple cuando al menos un valor coincide. Cambia el cuantificador a «todos» cuando todos los valores deban coincidir; con «no es» equivale a «no es ninguno». Una condición también puede nombrar un alias de captura: el valor ganador queda disponible para las plantillas de acción como <code>{{ match.&lt;alias&gt; }}</code> (o <code>{{ match.&lt;posición&gt; }}</code> sin alias). Debajo de las condiciones siempre obligatorias puedes añadir hasta cuatro <strong>alternativas</strong>: grupos cuyas condiciones deben cumplirse todas dentro del grupo, y basta con que un solo grupo se cumpla para que el evento se dispare.</p><p>Las pruebas pueden ejecutar los efectos configurados. Lee la lista seleccionada antes de pulsar <strong>Test</strong> o disparar un evento, especialmente si incluye audio, HTTP, puntos o plugins. Aprende primero con registros.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Resultado esperado y estado”">​</a></h2><p>Están disponibles la edición local, la ejecución, las plantillas, los perfiles y el historial. Los disparadores de plugins aparecen mientras su plugin está instalado y activo. La activación depende de la superficie y de los valores enabled revisados; comprueba eventos y acciones antes de confirmar. <strong>Changes</strong> en Eventos/Acciones es una <a href="./../cloud/changes.html">comparación local</a>, sin subida automática a Cloud.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to “Recuperación”">​</a></h2><p>Si no se ejecuta, comprueba perfil activo, interruptores, disparador, filtros, espera y acciones ausentes, en ese orden. Ante un conflicto de revisión, vuelve a leer la definición guardada y revísala. Evita sobrescribir a ciegas cambios ajenos. Exporta un <a href="./templates.html">perfil</a> conocido antes de modificaciones amplias.</p><h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Detalles de operación”">​</a></h2><p>Antes de cambiar perfil/importar, lee <a href="./templates.html#operational-details">activación por superficie</a>. El cambio puede activar miembros deshabilitados individualmente. El cooldown vive en memoria, con máximo 24 horas; sin uniqueId los espectadores comparten ámbito anónimo. La tabla se vacía al alcanzar 8.192 claves: sobrecarga o reinicio pueden permitir ejecuciones adicionales. No es cuota durable ni garantía de replay.</p><p>Pruébalo interactivamente antes de tocar tu configuración real:</p>`,15),t(d,{scenario:`automation`,locale:`es`,panel:`automation`,title:`Prueba el espacio de automatizaciones`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">Operaciones de línea de comandos <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Operaciones de línea de comandos”">​</a></h2><p>Cada operación de esta guía también está disponible desde la CLI: sin conexión, scriptable y apta para agentes. Las líneas de uso son sintaxis del parser y permanecen en inglés en todos los idiomas.</p><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools automation list [--kind event&amp;#124;action&amp;#124;all]</code></td><td>listar las reglas de automatización</td></tr><tr><td><code>tiktools automation context [--event-type t]</code></td><td>contexto de plantilla disponible para las reglas</td></tr><tr><td><code>tiktools automation get &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>leer una regla</td></tr><tr><td><code>tiktools automation create --record json [--kind event&amp;#124;action]</code></td><td>crear una regla</td></tr><tr><td><code>tiktools automation update &lt;id&gt; --record json [--kind event&amp;#124;action]</code></td><td>actualizar una regla</td></tr><tr><td><code>tiktools automation delete &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>eliminar una regla <strong>destructivo</strong></td></tr><tr><td><code>tiktools automation enable &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>activar una regla</td></tr><tr><td><code>tiktools automation disable &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>desactivar una regla</td></tr><tr><td><code>tiktools automation test (--id &lt;id&gt; &amp;#124; --record json) [--kind event&amp;#124;action] [--trigger t] [--event json]</code></td><td>probar una regla en seco contra un evento de muestra</td></tr><tr><td><code>tiktools automation fire --trigger &lt;type&gt; [--event json] [--record json]</code></td><td>disparar un trigger manualmente</td></tr><tr><td><code>tiktools automation moderation-penalty --points &lt;delta&gt;</code></td><td>aplicar una penalización de moderación en puntos</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools workflow list</code></td><td>listar los grafos de workflow guardados</td></tr><tr><td><code>tiktools workflow get &lt;id&gt;</code></td><td>leer un grafo</td></tr><tr><td><code>tiktools workflow save --record json</code></td><td>crear o reemplazar un grafo</td></tr><tr><td><code>tiktools workflow delete &lt;id&gt;</code></td><td>eliminar un grafo <strong>destructivo</strong></td></tr><tr><td><code>tiktools workflow enable &lt;id&gt;</code></td><td>activar un grafo</td></tr><tr><td><code>tiktools workflow disable &lt;id&gt;</code></td><td>desactivar un grafo</td></tr></tbody></table><p>Consulta la <a href="./../../developer/cli.html">referencia completa de comandos</a> para las convenciones, la salida JSON y los marcadores de operaciones destructivas.</p>`,5)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};